import numpy as np
from PIL import Image
from collections import deque

a = np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
h, w, _ = a.shape
R,G,B = a[...,0], a[...,1], a[...,2]
mx = a.max(2); mn = a.min(2); sat = mx-mn

# block masks: vivid colors
yellow = (R>180)&(G>150)&(B<110)&(sat>70)
red    = (R>120)&(G<90)&(B<90)&(R-G>60)
green  = (G>100)&(R<150)&(B<120)&(G-R>25)&(sat>40)
blue   = (B>100)&(R<110)&(B-G>25)

def components(mask, min_area=20):
    seen = np.zeros_like(mask, bool)
    out=[]
    for sy in range(h):
        for sx in range(w):
            if mask[sy,sx] and not seen[sy,sx]:
                q=deque([(sy,sx)]); seen[sy,sx]=True; pts=[]
                while q:
                    y,x=q.popleft(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx))
                if len(pts)>=min_area:
                    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                    out.append((len(pts), min(xs),max(xs),min(ys),max(ys)))
    return sorted(out, reverse=True)

for name,m in [(\"yellow\",yellow),(\"red\",red),(\"green\",green),(\"blue\",blue)]:
    comps = components(m)
    print(name, \"components (area,x0,x1,y0,y1):\")
    for c in comps[:8]: print(\"  \", c)
